-- Solo crea el módulo de seguridad. No modifica ni borra datos del sistema de ventas.
BEGIN
    EXECUTE IMMEDIATE 'CREATE TABLE roles (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR2(30) NOT NULL, descripcion VARCHAR2(150))';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN
    EXECUTE IMMEDIATE 'CREATE TABLE empleados (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, dni VARCHAR2(8) NOT NULL, nombres VARCHAR2(100) NOT NULL, apellidos VARCHAR2(100) NOT NULL, cargo VARCHAR2(60) NOT NULL, email VARCHAR2(150) NOT NULL, telefono VARCHAR2(15), estado BOOLEAN NOT NULL, fecha_creacion TIMESTAMP NOT NULL, fecha_modificacion TIMESTAMP)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN
    EXECUTE IMMEDIATE 'CREATE TABLE usuarios (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR2(50) NOT NULL, password VARCHAR2(100) NOT NULL, estado BOOLEAN NOT NULL, empleado_id NUMBER NOT NULL UNIQUE, fecha_creacion TIMESTAMP NOT NULL, fecha_modificacion TIMESTAMP, CONSTRAINT fk_usuarios_empleado FOREIGN KEY (empleado_id) REFERENCES empleados(id))';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN
    EXECUTE IMMEDIATE 'CREATE TABLE usuario_roles (usuario_id NUMBER NOT NULL, rol_id NUMBER NOT NULL, CONSTRAINT pk_usuario_roles PRIMARY KEY (usuario_id, rol_id), CONSTRAINT fk_usuario_roles_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id), CONSTRAINT fk_usuario_roles_rol FOREIGN KEY (rol_id) REFERENCES roles(id))';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX uk_roles_nombre ON roles(nombre)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX uk_empleados_dni ON empleados(dni)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX uk_empleados_email ON empleados(email)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX uk_usuarios_username ON usuarios(username)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408) THEN RAISE; END IF; END;
/

INSERT INTO roles (nombre, descripcion) SELECT 'ADMIN', 'Administración completa del sistema' FROM dual WHERE NOT EXISTS (SELECT 1 FROM roles WHERE nombre = 'ADMIN');
