INSERT INTO usuario_roles (usuario_id, rol_id) SELECT u.id, r.id FROM usuarios u CROSS JOIN roles r WHERE u.username = 'admin' AND r.nombre = 'ADMIN' AND NOT EXISTS (SELECT 1 FROM usuario_roles ur WHERE ur.usuario_id = u.id AND ur.rol_id = r.id);
INSERT INTO usuario_roles (usuario_id, rol_id) SELECT u.id, r.id FROM usuarios u CROSS JOIN roles r WHERE u.username = 'vendedor' AND r.nombre = 'VENDEDOR' AND NOT EXISTS (SELECT 1 FROM usuario_roles ur WHERE ur.usuario_id = u.id AND ur.rol_id = r.id);
INSERT INTO usuario_roles (usuario_id, rol_id) SELECT u.id, r.id FROM usuarios u CROSS JOIN roles r WHERE u.username = 'almacenero' AND r.nombre = 'ALMACENERO' AND NOT EXISTS (SELECT 1 FROM usuario_roles ur WHERE ur.usuario_id = u.id AND ur.rol_id = r.id);
